from datetime import datetime, timedelta

def iso_to_dt(s):
    return datetime.fromisoformat(s.replace('Z','+00:00')) if s else None

# Login to Gmail
acct_pw = [x for x in apis.supervisor.show_account_passwords() if x['account_name']=='gmail'][0]['password']
login_resp = apis.gmail.login(username='jefsmith@gmail.com', password=acct_pw)
access_token = login_resp['access_token']
our_email = 'jefsmith@gmail.com'
now = datetime.now()
min_date = (now - timedelta(days=7)).date().isoformat()
max_date = now.date().isoformat()

# Recompute eligible actions exactly as before to ensure payload matches current data
page_index = 0
page_limit = 20
threads = []
while True:
    resp = apis.gmail.show_outbox_threads(
        access_token=access_token,
        from_email=our_email,
        min_created_at=min_date,
        max_created_at=max_date,
        page_index=page_index,
        page_limit=page_limit
    )
    if not resp:
        break
    threads.extend(resp)
    if len(resp) < page_limit:
        break
    page_index += 1

job_keywords = ['application', 'employment', 'consideration', 'job applications', 'candidate', 'resume', 'search', 'open position', 'position', 'applying for']

def looks_job_subject(subject):
    s = (subject or '').lower()
    return any(k in s for k in job_keywords)

eligible_actions = []

for t in threads:
    thread_id = t['email_thread_id']
    thread = apis.gmail.show_thread(email_thread_id=thread_id, access_token=access_token)

    sent_job_emails = []
    reminder_emails = []

    for e in thread['emails']:
        if e['sender']['email'].lower() != our_email.lower():
            continue
        created = iso_to_dt(e.get('created_at'))
        subj = e.get('subject','')
        body = (e.get('body') or '')
        recipients = [r['email'] for r in e.get('recipients', [])]
        email_id = e['email_id']

        if looks_job_subject(subj):
            sent_job_emails.append({'email_id': email_id, 'created_at': created, 'subject': subj, 'recipients': recipients})
        if body.strip() == 'A polite reminder.':
            reminder_emails.append({'reminder_email_id': email_id, 'created_at': created})

    if not sent_job_emails:
        continue

    reminder_response_map = {}
    for r in reminder_emails:
        info = apis.gmail.show_email(email_id=r['reminder_email_id'], access_token=access_token)
        reminder_response_map[r['reminder_email_id']] = info.get('response_to_email_id')

    for js in sent_job_emails:
        if not js['created_at']:
            continue
        hours_since = (now - js['created_at']).total_seconds()/3600.0

        replied_after = False
        for e in thread['emails']:
            if e['sender']['email'].lower() == our_email.lower():
                continue
            created = iso_to_dt(e.get('created_at'))
            if created and js['created_at'] and created > js['created_at']:
                replied_after = True
                break

        reminder_already = False
        for reminder_email_id, response_to in reminder_response_map.items():
            if response_to == js['email_id']:
                reminder_already = True
                break

        if (hours_since > 72) and (not replied_after) and (not reminder_already):
            eligible_actions.append({
                'thread_id': thread_id,
                'email_id': js['email_id'],
                'email_addresses': js['recipients'],
                'hours_since': hours_since,
                'job_subject': js['subject'],
            })

print('Eligible reminders to send:', len(eligible_actions))
for a in eligible_actions:
    # confirm that there is no existing reminder response to this exact email
    thread = apis.gmail.show_thread(email_thread_id=a['thread_id'], access_token=access_token)
    prior = []
    for e in thread['emails']:
        if e['sender']['email'].lower() == our_email.lower() and (e.get('body') or '').strip() == 'A polite reminder.':
            info = apis.gmail.show_email(email_id=e['email_id'], access_token=access_token)
            if info.get('response_to_email_id') == a['email_id']:
                prior.append(e['email_id'])
    print({'thread_id': a['thread_id'], 'job_email_id': a['email_id'], 'recipients': a['email_addresses'], 'hours_since': round(a['hours_since'],2), 'prior_reminder_responses_to_this_email': prior})

print('---\nPayload to send (do not send yet):')
for a in eligible_actions:
    print({'email_thread_id': a['thread_id'], 'email_id': a['email_id'], 'email_addresses': a['email_addresses'], 'body': 'A polite reminder.'})

